#include <stdio.h>
#include <string.h>
#include <openssl/hmac.h>

int verify_signature(const char *secret, const char *body, size_t body_len,
                     const char *sig_hex) {
  unsigned char mac[EVP_MAX_MD_SIZE];
  unsigned int mac_len = 0;
  char hex[EVP_MAX_MD_SIZE * 2 + 1];
  HMAC_CTX *ctx = HMAC_CTX_new();
  HMAC_Init_ex(ctx, secret, strlen(secret), EVP_sha256(), NULL);
  HMAC_Update(ctx, (const unsigned char *)body, body_len);
  HMAC_Final(ctx, mac, &mac_len);
  HMAC_CTX_free(ctx);
  for (unsigned int i = 0; i < mac_len; i++) {
    sprintf(hex + i * 2, "%02x", mac[i]);
  }
  return strcmp(hex, sig_hex) == 0;
}

