#include <stdio.h>
#include <string.h>
#include <openssl/core_names.h>
#include <openssl/crypto.h>
#include <openssl/evp.h>

int verify_signature(const char *secret, const char *body, size_t body_len,
                     const char *sig_hex) {
  unsigned char mac[EVP_MAX_MD_SIZE];
  size_t mac_len = 0;
  char hex[EVP_MAX_MD_SIZE * 2 + 1];
  int ok = 0;
  EVP_MAC *hmac = EVP_MAC_fetch(NULL, "HMAC", NULL);
  EVP_MAC_CTX *ctx = hmac != NULL ? EVP_MAC_CTX_new(hmac) : NULL;
  OSSL_PARAM params[] = {
    OSSL_PARAM_construct_utf8_string(OSSL_MAC_PARAM_DIGEST, "SHA256", 0),
    OSSL_PARAM_construct_end(),
  };
  if (ctx == NULL) goto done;
  if (EVP_MAC_init(ctx, (const unsigned char *)secret, strlen(secret), params) != 1) goto done;
  if (EVP_MAC_update(ctx, (const unsigned char *)body, body_len) != 1) goto done;
  if (EVP_MAC_final(ctx, mac, &mac_len, sizeof mac) != 1) goto done;
  for (size_t i = 0; i < mac_len; i++) {
    snprintf(hex + i * 2, 3, "%02x", mac[i]);
  }
  size_t n = strlen(sig_hex);
  ok = CRYPTO_memcmp(hex, sig_hex, n) == 0;
done:
  EVP_MAC_CTX_free(ctx);
  EVP_MAC_free(hmac);
  return ok;
}
